/*
 * The classifynext block: finds the next protocol and records it at
 * previous_index + 1. A case that sets no nextencaps classifies nothing.
 */
static mmt_classify_verdict_t tpkt_example_classify_next(ipacket_t *ipacket, unsigned previous_index)
{
    classified_proto_t next;
    int ok = 1;
    int classified = 0;
    int64_t offset = 0;
    int64_t subject = tpkt_example_val_version(ipacket, previous_index, &ok);

    if (!ok) {
        return MMT_CLASSIFY_SKIP;
    }
    memset(&next, 0, sizeof(next));
    switch (subject) {
    case 3: /* TPKT_VERSION */
        next.proto_id = 979; /* COTP_EXAMPLE */
        classified = 1;
        offset = 4;
        break;
    }
    if (!ok || !classified || offset < 0 || offset > UINT16_MAX) {
        return MMT_CLASSIFY_SKIP;
    }
    next.offset = (uint16_t) offset;
    next.status = Classified;
    if (!set_classified_proto(ipacket, previous_index + 1, next)) {
        return MMT_CLASSIFY_SKIP;
    }
    return MMT_CLASSIFY_MATCHED;
}

